DB_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "news.db")
SITE_NAME = "South Asian Mirror"

BN = str.maketrans("0123456789", "০১২৩৪৫৬৭৮৯")
MONTHS = ["জানুয়ারি", "ফেব্রুয়ারি", "মার্চ", "এপ্রিল", "মে", "জুন",
          "জুলাই", "আগস্ট", "সেপ্টেম্বর", "অক্টোবর", "নভেম্বর", "ডিসেম্বর"]
CATEGORIES = [("bangladesh", "বাংলাদেশ"), ("politics", "রাজনীতি"),
              ("economy", "অর্থনীতি"), ("sports", "খেলা"),
              ("entertainment", "বিনোদন"), ("technology", "প্রযুক্তি"),
              ("world", "আন্তর্জাতিক")]


# ---------- Database ----------
def db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(_):
    conn = g.pop("db", None)
    if conn:
        conn.close()


def init_db():
    conn = sqlite3.connect(DB_PATH)
    conn.executescript("""
    CREATE TABLE IF NOT EXISTS categories(
        id INTEGER PRIMARY KEY, slug TEXT UNIQUE, name TEXT);
    CREATE TABLE IF NOT EXISTS articles(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL, summary TEXT, body TEXT NOT NULL,
        category_id INTEGER, image_url TEXT, is_lead INTEGER DEFAULT 0,
        views INTEGER DEFAULT 0,
        created_at TEXT DEFAULT (strftime('%Y-%m-%d %H:%M','now','localtime')));
    """)
    if conn.execute("SELECT COUNT(*) FROM categories").fetchone()[0] == 0:
        conn.executemany("INSERT INTO categories(slug,name) VALUES(?,?)", CATEGORIES)
        samples = [
            ("নমুনা লিড সংবাদ: নতুন নিউজ পোর্টালের যাত্রা শুরু",
             "অ্যাডমিন প্যানেল থেকে এই সংবাদ মুছে নিজের খবর যোগ করুন।",
             "এটি একটি নমুনা সংবাদ।\nঅ্যাডমিন প্যানেলে লগইন করে নতুন সংবাদ যোগ, সম্পাদনা ও মুছে ফেলতে পারবেন।", 1, 1),
            ("নমুনা খেলার খবর", "খেলার ক্যাটাগরির একটি নমুনা সংবাদ।", "বিস্তারিত সংবাদ এখানে থাকবে।", 4, 0),
            ("নমুনা প্রযুক্তির খবর", "প্রযুক্তি ক্যাটাগরির একটি নমুনা সংবাদ।", "বিস্তারিত সংবাদ এখানে থাকবে।", 6, 0),
            ("নমুনা অর্থনীতির খবর", "অর্থনীতি ক্যাটাগরির একটি নমুনা সংবাদ।", "বিস্তারিত সংবাদ এখানে থাকবে।", 3, 0),
        ]
        for t, s, b, c, lead in samples:
            conn.execute("INSERT INTO articles(title,summary,body,category_id,is_lead) VALUES(?,?,?,?,?)",
                         (t, s, b, c, lead))
    conn.commit()
    conn.close()


# ---------- Template helpers ----------
@app.template_filter("bn")
def bn(v):
    return str(v).translate(BN)


@app.template_filter("bdate")
def bdate(s):
    d = datetime.strptime(s[:16], "%Y-%m-%d %H:%M")
    return f"{d.day} {MONTHS[d.month - 1]} {d.year}, {d.strftime('%H:%M')}".translate(BN)


@app.context_processor
def inject():
    d = datetime.now()
    today = f"{d.day} {MONTHS[d.month - 1]} {d.year}".translate(BN)
    return dict(nav_cats=db().execute("SELECT * FROM categories").fetchall(),
                site_name=SITE_NAME, today=today, logo_b64=LOGO_B64)


def admin_required(f):
    @wraps(f)
    def wrap(*a, **kw):
        if not session.get("admin"):
            return redirect(url_for("login"))
        return f(*a, **kw)
    return wrap


BASE_Q = ("SELECT a.*, c.name AS cat_name, c.slug AS cat_slug FROM articles a "
          "LEFT JOIN categories c ON c.id=a.category_id ")


# ---------- Public routes ----------
@app.route("/")
def index():
    d = db()
    lead = d.execute(BASE_Q + "ORDER BY a.is_lead DESC, a.id DESC LIMIT 1").fetchone()
    lead_id = lead["id"] if lead else 0
    latest = d.execute(BASE_Q + "WHERE a.id!=? ORDER BY a.id DESC LIMIT 4", (lead_id,)).fetchall()
    popular = d.execute(BASE_Q + "ORDER BY a.views DESC, a.id DESC LIMIT 5").fetchall()
    sections = []
    for c in d.execute("SELECT * FROM categories").fetchall():
        items = d.execute(BASE_Q + "WHERE a.category_id=? ORDER BY a.id DESC LIMIT 3", (c["id"],)).fetchall()
        if items:
            sections.append((c, items))
    return render_template("index.html", lead=lead, latest=latest, popular=popular, sections=sections)


@app.route("/category/<slug>")
def category(slug):
    d = db()
    cat = d.execute("SELECT * FROM categories WHERE slug=?", (slug,)).fetchone() or abort(404)
    items = d.execute(BASE_Q + "WHERE a.category_id=? ORDER BY a.id DESC", (cat["id"],)).fetchall()
    return render_template("category.html", cat=cat, items=items)


@app.route("/news/<int:aid>")
def article(aid):
    d = db()
    a = d.execute(BASE_Q + "WHERE a.id=?", (aid,)).fetchone() or abort(404)
    d.execute("UPDATE articles SET views=views+1 WHERE id=?", (aid,))
    d.commit()
    related = d.execute(BASE_Q + "WHERE a.category_id=? AND a.id!=? ORDER BY a.id DESC LIMIT 3",
                        (a["category_id"], aid)).fetchall()
    return render_template("article.html", a=a, related=related)


# ---------- Admin routes ----------
@app.route("/admin/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        if request.form.get("password") == ADMIN_PASSWORD:
            session["admin"] = True
            return redirect(url_for("admin"))
        flash("পাসওয়ার্ড সঠিক নয়")
    return render_template("login.html")


@app.route("/admin/logout")
def logout():
    session.clear()
    return redirect(url_for("index"))


@app.route("/admin")
@admin_required
def admin():
    items = db().execute(BASE_Q + "ORDER BY a.id DESC").fetchall()
    return render_template("admin.html", items=items)


def save_article(aid=None):
    f = request.form
    vals = (f["title"].strip(), f["summary"].strip(), f["body"].strip(),
            int(f["category_id"]), f["image_url"].strip(), 1 if f.get("is_lead") else 0)
    d = db()
    if vals[5]:
        d.execute("UPDATE articles SET is_lead=0")
    if aid:
        d.execute("UPDATE articles SET title=?,summary=?,body=?,category_id=?,image_url=?,is_lead=? WHERE id=?",
                  vals + (aid,))
    else:
        d.execute("INSERT INTO articles(title,summary,body,category_id,image_url,is_lead) VALUES(?,?,?,?,?,?)", vals)
    d.commit()


@app.route("/admin/new", methods=["GET", "POST"])
@admin_required
def new_article():
    if request.method == "POST":
        save_article()
        return redirect(url_for("admin"))
    return render_template("form.html", a=None)


@app.route("/admin/edit/<int:aid>", methods=["GET", "POST"])
@admin_required
def edit_article(aid):
    a = db().execute("SELECT * FROM articles WHERE id=?", (aid,)).fetchone() or abort(404)
    if request.method == "POST":
        save_article(aid)
        return redirect(url_for("admin"))
    return render_template("form.html", a=a)


@app.route("/admin/delete/<int:aid>", methods=["POST"])
@admin_required
def delete_article(aid):
    db().execute("DELETE FROM articles WHERE id=?", (aid,))
    db().commit()
    return redirect(url_for("admin"))


